import React, { useState } from 'react';
import { TwitterTimelineEmbed } from 'react-twitter-embed';
import Skeleton from 'react-loading-skeleton';
import 'react-loading-skeleton/dist/skeleton.css';
import './Twitter.css';

const Twitter = () => {
    const [activeTab, setActiveTab] = useState('premierleague');
    const [loading, setLoading] = useState(true);
    const [loaded, setLoaded] = useState(false);

    const handleLoad = () => {
        setLoaded(true);
        setLoading(false);
    };

    const renderTabContent = () => {
        switch (activeTab) {
            case 'premierleague':
                return (
                    <TwitterTimelineEmbed
                        key="premierleague"
                        sourceType="profile"
                        screenName="premierleague"
                        options={{ height: 800, width: '67%' }}
                        onLoad={handleLoad}
                    />
                );
            case 'bbcnews':
                return (
                    <TwitterTimelineEmbed
                        key="bbcnews"
                        sourceType="profile"
                        screenName="BBCNews"
                        options={{ height: 800, width: '67%' }}
                        onLoad={handleLoad}
                    />
                );
            case 'cnn':
                return (
                    <TwitterTimelineEmbed
                        key="cnn"
                        sourceType="profile"
                        screenName="CNN"
                        options={{ height: 800, width: '67%' }}
                        onLoad={handleLoad}
                    />
                );
            default:
                return null;
        }
    };

    return (
        <div className="twitter-page">
            <h1>Twitter Feeds</h1>
            <div className="tabs">
                <button className={activeTab === 'premierleague' ? 'active' : ''} onClick={() => { setActiveTab('premierleague'); setLoading(true); setLoaded(false); }}>Premier League</button>
                <button className={activeTab === 'bbcnews' ? 'active' : ''} onClick={() => { setActiveTab('bbcnews'); setLoading(true); setLoaded(false); }}>BBC News</button>
                <button className={activeTab === 'cnn' ? 'active' : ''} onClick={() => { setActiveTab('cnn'); setLoading(true); setLoaded(false); }}>CNN</button>
            </div>
            <div className="tab-content">
                {loading && !loaded && <Skeleton height={800} />}
                {(loading || loaded) && renderTabContent()}
            </div>
        </div>
    );
};

export default Twitter;